      "Effect": "Allow",
      "Action": "ec2:RebootInstances",
      "Resource": [
        "arn:aws:ec2:eu-west-1:123456789012:instance/i-0abc1111",
        "arn:aws:ec2:eu-west-1:123456789012:instance/i-0abc2222"
      ]
    },
    {
      "Sid": "NuncaBorrar",
      "Effect": "Deny",
      "Action": "ec2:TerminateInstances",
      "Resource": "*"
    }
